package com.asapp

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/** Pictures stored inside the code (so only text files need to be uploaded). */
object Art {
    private val splashParts = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "hQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAKFChQAYOKHMaFCgAZoZoUKABmhmhQoAGaGaFCgAZoEnGKFCgAqFChQAKFChQAKFChQAKPNChQAVChQoAFChQoAFChQoAFChQoAFChQoAFChQoAFChQoAFChQoAFChQoAFChQoAFChQoA//9k="
    )
    private val logoParts = arrayOf(
        "",
        "",
        ""
    )

    private val headParts = arrayOf(
        "",
        "",
        "",
        ""
    )

    private fun decode(p: Array<String>): Bitmap {
        val bytes = Base64.decode(p.joinToString(""), Base64.DEFAULT)
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }
    private var sp: Bitmap? = null
    private var lg: Bitmap? = null
    private var hd: Bitmap? = null
    fun splash(): Bitmap { if (sp == null) sp = decode(splashParts); return sp!! }
    /** the brain-head logo used in the headers */
    fun head(): Bitmap { if (hd == null) hd = decode(headParts); return hd!! }
    /** the bubble logo of the login screen */
    fun logo(): Bitmap { if (lg == null) lg = decode(logoParts); return lg!! }
}
